// example: invoking SageMaker endpoint from Lambda (Node.js)
const AWS = require('aws-sdk');
const runtime = new AWS.SageMakerRuntime();
async function classify(text, endpoint){
  const res = await runtime.invokeEndpoint({EndpointName: endpoint, ContentType:'text/plain', Body: text}).promise();
  return JSON.parse(res.Body.toString())
}
```

